import{_ as n,a0 as a,w as d,s as p,I as t,x as s,a1 as r,A as o,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在樹莓派上運行 DOS 系統 | LCTT x X-CMD","titleTemplate":false,"description":"在樹莓派上運行 DOS 系統 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在樹莓派上運行 DOS 系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在樹莓派上運行 DOS 系統 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180313 Running DOS on the Raspberry Pi","title":"在樹莓派上運行 DOS 系統","tag":"201804","desc":""},"relativePath":"201804/20180313 Running DOS on the Raspberry Pi.md","filePath":"[post].md"}'),u={name:"201804/20180313 Running DOS on the Raspberry Pi.md"};function D(S,e,O,m,f,g){const i=a("Link");return d(),p("div",null,[e[38]||(e[38]=t("h1",{id:"在樹莓派上運行-dos-系統",tabindex:"-1"},[s("在樹莓派上運行 DOS 系統 "),t("a",{class:"header-anchor",href:"#在樹莓派上運行-dos-系統","aria-label":"Permalink to “在樹莓派上運行 DOS 系統”"},"​")],-1)),e[39]||(e[39]=t("blockquote",null,[t("p",null,"不同的 CPU 架構意味着在樹莓派上運行 DOS 並非唾手可得，但其實也沒多麻煩。")],-1)),e[40]||(e[40]=t("p",null,[t("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/wings_freedos_game.jpg?itok=7j8x-A-w",alt:""})],-1)),t("p",null,[r(i,{href:"http://www.freedos.org/"},{default:o(()=>[...e[0]||(e[0]=[s("FreeDOS",-1)])]),_:1}),e[1]||(e[1]=s(" 對大家來説也許並不陌生。它是一個完整、免費並且對 DOS 兼容良好的操作系統，它可以運行一些比較老舊的 DOS 遊戲或者商用軟件，也可以開發嵌入式的應用。只要在 MS-DOS 上能夠運行的程序，在 FreeDOS 上都可以運行。",-1))]),e[41]||(e[41]=l('<p>作為 FreeDOS 的發起者和項目協調人員，很多用户會把我作為內行人士進行發問。而我最常被問到的問題是：“FreeDOS 可以在樹莓派上運行嗎？”</p><p>這個問題並不令人意外。畢竟 Linux 在樹莓派上能夠很好地運行，而 FreeDOS 和 Linux 相比是一個更古老、佔用資源更少的操作系統，那 FreeDOS 為啥不能樹莓派上運行呢？</p><p>簡單來説。由於 CPU 架構的原因，FreeDOS 並不能在樹莓派中獨立運行。和其它 DOS 類的系統一樣，FreeDOS 需要英特爾 x86 架構 CPU 以及 BIOS 來提供基礎的運行時服務。而樹莓派運行在 ARM 架構的 CPU 上，與英特爾 CPU 二進制不兼容，也沒有 BIOS。因此樹莓派在硬件層面就不支持 FreeDOS。</p><p>不過通過 PC 模擬器還是能在樹莓派上運行 FreeDOS 的，雖然這樣也許稍有不足，但也不失為一個能在樹莓派上運行 FreeDOS 的方法。</p><h3 id="dosbox-怎麼樣" tabindex="-1">DOSBox 怎麼樣? <a class="header-anchor" href="#dosbox-怎麼樣" aria-label="Permalink to “DOSBox 怎麼樣?”">​</a></h3><p>有人可能會問：“為什麼不用 DOSBox 呢？” DOSBox 是一個開源的跨平台 x86 模擬器，在 Linux 上也能使用，它能夠為應用軟件尤其是遊戲軟件提供了一個類 DOS 的運行環境，所以如果你只是想玩 DOS 遊戲的話，DOSBox 是一個不錯的選擇。但在大眾眼中，DOSBox 是專為 DOS 遊戲而設的，而在運行一些別的 DOS 應用軟件方面，DOSBox 只是表現平平。</p><p>對多數人來説，這只是個人偏好的問題，我喜歡用 FreeDOS 來運行 DOS 遊戲和其它程序，完整的 DOS 系統和 DOSBox 相比能讓我體驗到更好的靈活性和操控性。我只用 DOSBox 來玩遊戲，在其它方面還是選擇完整的 FreeDOS。</p><h3 id="在樹莓派上安裝-freedos" tabindex="-1">在樹莓派上安裝 FreeDOS <a class="header-anchor" href="#在樹莓派上安裝-freedos" aria-label="Permalink to “在樹莓派上安裝 FreeDOS”">​</a></h3>',8)),t("p",null,[r(i,{href:"https://www.qemu.org/"},{default:o(()=>[...e[2]||(e[2]=[s("QEMU",-1)])]),_:1}),e[4]||(e[4]=s("（Quick EMUlator）是一款能在 Linux 系統上運行 DOS 系統的開源的虛擬機軟件。很多流行的 Linux 系統都自帶 QEMU。QEMU 在我的樹莓派上的 Raspbian 系統中也同樣能夠運行，下文就有一些我在樹莓派 ",-1)),r(i,{href:"https://www.raspberrypi.org/downloads/"},{default:o(()=>[...e[3]||(e[3]=[s("Raspbian GNU/Linux 9 (Stretch)",-1)])]),_:1}),e[5]||(e[5]=s(" 系統中使用 QEMU 的截圖。",-1))]),t("p",null,[e[7]||(e[7]=s("去年我在寫了一篇關於",-1)),r(i,{href:"https://linux.cn/article-9014-1.html"},{default:o(()=>[...e[6]||(e[6]=[s("如何在 Linux 系統中運行 DOS 程序",-1)])]),_:1}),e[8]||(e[8]=s("的文章的時候就用到了 QEMU，在樹莓派上使用 QEMU 來安裝運行 FreeDOS 的步驟基本上和在別的基於 GNOME 的系統上沒有什麼太大的區別。",-1))]),e[42]||(e[42]=l('<p>在 QEMU 中你需要通過添加各種組件來搭建虛擬機。先指定一個用來安裝運行 DOS 的虛擬磁盤鏡像，通過 <code>qemu-img</code> 命令來創建一個虛擬磁盤鏡像，對於 FreeDOS 來説不需要太大的空間，所以我只創建了一個 200MB 的虛擬磁盤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>qemu-img create freedos.img 200M</span></span></code></pre></div><p>和 VMware 或者 VirtualBox 這些 PC 模擬器不同，使用 QEMU 需要通過添加各種組件來搭建虛擬機，儘管有點麻煩，但是並不困難。我使用了以下這些參數來在樹莓派上使用 QEMU 安裝 FreeDOS 系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>qemu-system-i386 -m 16 -k en-us -rtc base=localtime -soundhw sb16,adlib -device cirrus-vga -hda freedos.img -cdrom FD12CD.iso -boot order=d</span></span></code></pre></div>',4)),t("p",null,[e[10]||(e[10]=s("你可以在我其它的",-1)),r(i,{href:"https://linux.cn/article-9014-1.html"},{default:o(()=>[...e[9]||(e[9]=[s("文章",-1)])]),_:1}),e[11]||(e[11]=s("中找到這些命令的完整介紹。簡單來説，上面這條命令指定了一個英特爾 i386 兼容虛擬機，並且分配了 16MB 內存、一個英文輸入鍵盤、一個基於系統時間的實時時鐘、一個聲卡、一個音樂卡以及一個 VGA 卡。文件 ",-1)),e[12]||(e[12]=t("code",null,"freedos.img",-1)),e[13]||(e[13]=s(" 指定為第一個硬盤（",-1)),e[14]||(e[14]=t("code",null,"C:",-1)),e[15]||(e[15]=s("），",-1)),e[16]||(e[16]=t("code",null,"FD12CD.iso",-1)),e[17]||(e[17]=s(" 鏡像作為 CD-ROM （",-1)),e[18]||(e[18]=t("code",null,"D:",-1)),e[19]||(e[19]=s("）驅動。QEMU 設定為從 ",-1)),e[20]||(e[20]=t("code",null,"D:",-1)),e[21]||(e[21]=s(" 的 CD-ROM 啓動。",-1))]),e[43]||(e[43]=l('<p>你只需要按照提示就可以輕鬆安裝好 FreeDOS 1.2 了。但是由於 microSD 卡在面對大量的 I/O 時速度比較慢，所以安裝操作系統需要花費很長時間。</p><h3 id="在樹莓派上運行-freedos" tabindex="-1">在樹莓派上運行 FreeDOS <a class="header-anchor" href="#在樹莓派上運行-freedos" aria-label="Permalink to “在樹莓派上運行 FreeDOS”">​</a></h3><p>你的運行情況取決於使用哪一種 microSD 卡。我用的是 SanDisk Ultra 64GB microSDXC UHS-I U1A1 ，其中 U1 這種型號專用於支持 1080p 的視頻錄製（例如 GoPro），它的最低串行寫速度能夠達到 10MB/s。相比之下，V60 型號專用於 4K 視頻錄製，最低連續寫入速度能達到 60MB/s。如果你的樹莓派使用的是 V60 的 microSD 卡甚至是 V30（也能達到 30MB/s），你就能明顯看到它的 I/O 性能會比我的好。</p><p>FreeDOS 安裝好之後，你可以直接從 <code>C:</code> 進行啓動。只需要按照下面的命令用 <code>-boot order=c</code> 來指定 QEMU 的啓動順序即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>​qemu-system-i386 -m 16 -k en-us -rtc base=localtime -soundhw sb16,adlib -device cirrus-vga -hda freedos.img -cdrom FD12CD.iso -boot order=c​</span></span></code></pre></div><p>只要樹莓派的 QEMU 上安裝了 FreeDOS，就不會出現明顯的性能問題。例如遊戲通常在每一關開始的時候會加載地圖、怪物、聲音等一系列的數據，儘管這些內容需要加載一段時間，但在正常玩的時候並沒有出現性能不足的現象。</p><p>FreeDOS 1.2 自帶了很多遊戲以及其它應用軟件，可以使用 <code>FDIMPLES</code> 包管理程序來安裝它們。FreeDOS 1.2 裏面我最喜歡的是一款叫 WING 的太空射擊遊戲，讓人想起經典的街機遊戲 Galaga（WING 就是 Wing Is Not Galaga 的遞歸縮寫詞）。</p>',7)),t("p",null,[e[23]||(e[23]=s("As-Easy-As 是我最喜歡的一個 DOS 應用程序，作為 20 世紀八九十年代流行的電子表格程序，它和當時的 Lotus 1-2-3 以及現在的 Microsoft Excel、LibreOffice Calc 一樣具有強大的威力。As-Easy-As 和 Lotus 1-2-3 都將數據保存為 WKS 文件，現在新版本的 Microsoft Excel 已經無法讀取這種文件了，而 LibreOffice Calc 視兼容性而定有可能支持。鑑於 As-Easy-As 的初始版本是一個共享軟件，TRIUS 仍然為 As-Easy-As 5.7 免費提供",-1)),r(i,{href:"http://www.triusinc.com/forums/viewtopic.php?t=10"},{default:o(()=>[...e[22]||(e[22]=[s("激活碼",-1)])]),_:1}),e[24]||(e[24]=s("。",-1))]),e[44]||(e[44]=t("p",null,[s("我也非常喜歡 GNU Emacs 編輯器，FreeDOS 也自帶了一個叫 Freemacs 的類 Emacs 的文本編輯器。它比 FreeDOS 默認的 FreeDOS Edit 編輯器更強大，也能帶來 GNU Emacs 的體驗。如果你也需要，可以在 FreeDOS 1.2 中通過"),t("code",null,"FDIMPLES"),s("包管理程序來安裝。")],-1)),e[45]||(e[45]=t("h3",{id:"是的-你或許真的可以在樹莓派上運行-dos",tabindex:"-1"},[s("是的，你或許真的可以在樹莓派上運行 DOS "),t("a",{class:"header-anchor",href:"#是的-你或許真的可以在樹莓派上運行-dos","aria-label":"Permalink to “是的，你或許真的可以在樹莓派上運行 DOS”"},"​")],-1)),e[46]||(e[46]=t("p",null,"即使樹莓派在硬件上不支持 DOS，但是在模擬器的幫助下，DOS 還是能夠在樹莓派上運行。得益於 QEMU PC 模擬器，一些經典的 DOS 遊戲和 DOS 應用程序能夠運行在樹莓派上。在執行磁盤 I/O ，尤其是大量密集操作（例如寫入大量數據）的時候，性能可能會受到輕微的影響。當你使用 QEMU 並且在虛擬機裏安裝好 FreeDOS 之後，你就可以盡情享受經典的 DOS 程序了。",-1)),e[47]||(e[47]=t("hr",null,null,-1)),t("p",null,[e[26]||(e[26]=s("via: ",-1)),r(i,{href:"https://opensource.com/article/18/3/can-you-run-dos-raspberry-pi"},{default:o(()=>[...e[25]||(e[25]=[s("https://opensource.com/article/18/3/can-you-run-dos-raspberry-pi",-1)])]),_:1})]),t("p",null,[e[30]||(e[30]=s("作者：",-1)),r(i,{href:"https://opensource.com/users/jim-hall"},{default:o(()=>[...e[27]||(e[27]=[s("Jim Hall",-1)])]),_:1}),e[31]||(e[31]=s(" 譯者：",-1)),r(i,{href:"https://github.com/HankChow"},{default:o(()=>[...e[28]||(e[28]=[s("HankChow",-1)])]),_:1}),e[32]||(e[32]=s(" 校對：",-1)),r(i,{href:"https://github.com/wxy"},{default:o(()=>[...e[29]||(e[29]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[35]||(e[35]=s("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[33]||(e[33]=[s("LCTT",-1)])]),_:1}),e[36]||(e[36]=s(" 原創編譯，",-1)),r(i,{href:"https://linux.cn/"},{default:o(()=>[...e[34]||(e[34]=[s("Linux中國",-1)])]),_:1}),e[37]||(e[37]=s(" 榮譽推出",-1))])])}const k=n(u,[["render",D]]);export{C as __pageData,k as default};
